//! A shape's Rust views (types §1, crossing §2): by value, a struct or an enum
//! of owned fields; by reference, its projection, a guard at each leaf. The
//! views are generated by `shape!`.

use crate::runtime::Runtime;

/// The projections of a transparent structured type, shared and exclusive.
pub trait Projected<R: Runtime> {
    type Ref<'a>;
    type Mut<'a>;
}
